 fn hex(bytes: &[u8]) -> String { const H: &[u8;16] = b"0123456789abcdef"; let mut s=String::with_capacity(bytes.len()*2); for &b in bytes { s.push(H[(b>>4) as usize] as char); s.push(H[(b&15) as usize] as char); } s }
+
+use aspis_statement::pool_v1::{PoolV1PairForestTerminalStatementV1, pair_forest_semantic_terminal::r0::Public};
+pub fn statement_public(statement: &PoolV1PairForestTerminalStatementV1) -> Public<'_> {
+    match statement {
+        PoolV1PairForestTerminalStatementV1::PrivateTransfer { common, public } => {
+            Public::Transfer(public, &common.lane_transition)
+        }
+        PoolV1PairForestTerminalStatementV1::Withdrawal { common, public } => {
+            Public::Withdrawal(public, &common.lane_transition)
+        }
+    }
+}
+pub fn host_hashv(inputs: &[&[u8]]) -> [u8; 32] {
+    use sha2::{Digest, Sha256};
+    let mut hasher = Sha256::new();
+    for input in inputs {
+        hasher.update(input);
+    }
+    hasher.finalize().into()
+}

